{"rob": "robolang 1.3;

task relay(robot a, robot b, object part, location src, location handoff, location dst, region fence) {
    goal { object_at part dst; }
    plan {
        move a to src;
        grasp a part;
        move a to handoff;
        place a part at handoff;
        wait until region_clear fence timeout 30 s;
        move b to handoff;
        grasp b part;
        move b to dst;
        place b part at dst;
    }
}
", "task": "relay", "bindings": [{"param": "a", "id": "arm_a"}, {"param": "b", "id": "arm_b"}, {"param": "part", "id": "p1"}, {"param": "src", "id": "conveyor_in"}, {"param": "handoff", "id": "handoff12"}, {"param": "dst", "id": "station3"}, {"param": "fence", "id": "fence_b"}]}
